export async function getStudentFeeStructure(id: string | number) {
  if (id === 'new' || !id) return null;
  const item = await prisma.studentFeeStructure.findUnique({
    where: { id: parseInt(String(id), 10) },
    include: { enrollment: true, program: true, paymentOption: true, batch: true, type: true },
  });

  return mapStudentFeeRow(item as any);
}

export async function saveStudentFeeStructure(data: any) {
  const { id, enrollmentNo, program, paymentOption, batch, type, ...restData } = data;

  try {
    const lookups = await resolveStudentFeeLookups({
      enrollmentNo,
      program,
      paymentOption,
      batch,
      type,
    });

    if (!lookups.enrollmentId) {
      return { error: 'Enrollment number is required' };
    }

    const feeFields = [
      'couponName', 'couponName2', 'couponName3',
      'sem1Fee', 'sem2Fee', 'sem3Fee', 'sem4Fee', 'sem5Fee', 'sem6Fee',
      'sem1Scholarship', 'sem2Scholarship', 'sem3Scholarship', 'sem4Scholarship', 'sem5Scholarship', 'sem6Scholarship',
      'sem1FeeAfter', 'sem2FeeAfter', 'sem3FeeAfter', 'sem4FeeAfter', 'sem5FeeAfter', 'sem6FeeAfter',
    ];

    const payload: any = { ...lookups };
    for (const key of feeFields) {
      if (key in restData && restData[key] !== undefined) {
        payload[key] = restData[key];
      }
    }

    if (id && id !== 'new') {
      await prisma.studentFeeStructure.update({
        where: { id: parseInt(String(id), 10) },
        data: payload,
      });
    } else {
      await prisma.studentFeeStructure.upsert({
        where: { enrollmentId: lookups.enrollmentId },
        update: payload,
        create: payload,
      });
    }
    revalidatePath('/student-fee-structure');
    return { success: true };
  } catch (error: unknown) {
    console.error(error);
    return { error: (error instanceof Error ? error.message : String(error)) };
  }
}

export async function deleteStudentFeeStructure(id: string | number) {
  try {
    await prisma.studentFeeStructure.delete({
      where: { id: parseInt(String(id), 10) },
    });
    revalidatePath('/student-fee-structure');
    return { success: true };
  } catch (error: unknown) {
    console.error(error);
    return { error: (error instanceof Error ? error.message : String(error)) };
  }
}

'use server';

import { prismaDelegate } from '@/lib/prisma-delegate';
import { getSession } from '@/lib/auth';
import { getTrackerTable } from '@/lib/tracker-tables';
import {
  hasBlockingIssues,
  rowHasBlockingIssue,
  validateTrackerRows,
  type TrackerInputRow,
} from '@/lib/tracker-bulk-upload';
import { revalidatePath } from 'next/cache';

async function requireAdmin() {
  const session = await getSession();
  if (session?.user?.role !== 'ADMIN') {
    throw new Error('Unauthorized');
  }
}

export async function getTrackerRows(slug: string) {
  await requireAdmin();
  const config = getTrackerTable(slug);
  if (!config) return null;

  const delegate = prismaDelegate(config.prismaModel);
  const rows = await delegate.findMany({ orderBy: { id: 'asc' } });
  return rows.map((row: any) => ({
    id: row.id as number,
    name: String(row[config.nameField] ?? ''),
  }));
}

export async function upsertTrackerRow(slug: string, id: number, name: string) {
  await requireAdmin();
  const config = getTrackerTable(slug);
  if (!config || !id || !name.trim()) {
    return { error: 'Invalid data' };
  }

  const delegate = prismaDelegate(config.prismaModel);
  try {
    await delegate.upsert({
      where: { id },
      update: { [config.nameField]: name.trim() },
      create: { id, [config.nameField]: name.trim() },
    });
    revalidatePath(`/tracker/${slug}`);
    return { success: true };
  } catch (e: unknown) {
    return { error: (e instanceof Error ? e.message : String(e)) || 'Failed to save' };
  }
}

export async function deleteTrackerRow(slug: string, id: number) {
  await requireAdmin();
  const config = getTrackerTable(slug);
  if (!config) return { error: 'Unknown table' };

  const delegate = prismaDelegate(config.prismaModel);
  try {
    await delegate.delete({ where: { id } });
    revalidatePath(`/tracker/${slug}`);
    return { success: true };
  } catch {
    return { error: 'Cannot delete — row may be linked to admission forms.' };
  }
}

export async function validateTrackerBulkUpload(
  slug: string,
  rows: { line: number; id: number | null; name: string; prefix?: string }[]
) {
  await requireAdmin();
  const config = getTrackerTable(slug);
  if (!config) return { error: 'Unknown table' as const };

  const existing = (await getTrackerRows(slug)) ?? [];
  const issues = validateTrackerRows(rows as TrackerInputRow[], existing);

  const result = rows.map(row => ({
    line: row.line,
    id: row.id,
    name: row.name,
    prefix: row.prefix,
    issues: issues.get(row.line) ?? [],
  }));

  return {
    rows: result,
    hasBlocking: hasBlockingIssues(issues),
    validCount: result.filter(r => !rowHasBlockingIssue(r.issues)).length,
  };
}

export async function bulkUpsertTrackerRows(
  slug: string,
  rows: { id: number; name: string; prefix?: string }[]
) {
  await requireAdmin();
  const config = getTrackerTable(slug);
  if (!config) return { error: 'Unknown table' };

  const existing = (await getTrackerRows(slug)) ?? [];
  const inputs: TrackerInputRow[] = rows.map((row, index) => ({
    line: index,
    id: row.id,
    name: row.name,
    prefix: row.prefix,
  }));
  const issues = validateTrackerRows(inputs, existing);

  const delegate = prismaDelegate(config.prismaModel);
  let saved = 0;
  let skipped = 0;
  const errors: string[] = [];

  for (let i = 0; i < rows.length; i++) {
    const row = rows[i];
    const rowIssues = issues.get(i) ?? [];
    if (rowHasBlockingIssue(rowIssues)) {
      skipped++;
      continue;
    }

    const data: Record<string, string> = { [config.nameField]: row.name.trim() };
    if (config.slug === 'enrollment' && row.prefix !== undefined) {
      data.prefix = row.prefix.trim();
    }

    try {
      await delegate.upsert({
        where: { id: row.id },
        update: data,
        create: { id: row.id, ...data },
      });
      saved++;
    } catch (e: unknown) {
      skipped++;
      errors.push(`id ${row.id}: ${(e instanceof Error ? e.message : String(e)) || 'Failed to save'}`);
    }
  }

  revalidatePath(`/tracker/${slug}`);
  return { success: true, saved, skipped, errors };
}

import { NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

export async function GET(request: Request) {
  const { searchParams } = new URL(request.url);
  const filter = searchParams.get('filter') || 'today';

  let gte: Date;
  let lte: Date;

  const now = new Date();

  if (filter === 'today') {
    gte = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    lte = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 23, 59, 59, 999);
  } else if (filter === 'yesterday') {
    gte = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 1);
    lte = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 1, 23, 59, 59, 999);
  } else if (filter === 'month') {
    const month = parseInt(searchParams.get('month') || String(now.getMonth()), 10);
    const year = parseInt(searchParams.get('year') || String(now.getFullYear()), 10);
    gte = new Date(year, month, 1);
    lte = new Date(year, month + 1, 0, 23, 59, 59, 999);
  } else {
    gte = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    lte = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 23, 59, 59, 999);
  }

  try {
    const payments = await prisma.consolidatedPayment.findMany({
      where: {
        date: { gte, lte },
        sourceName: { in: ['Razorpay', 'Jodo', 'Early', 'Offline', 'Bank', 'Propelld', 'Corp Inst'] }
      },
      select: {
        batch: { select: { batch: true } },
        sourceName: true,
        amount: true,
      },
    });

    const sources = ['Razorpay', 'Jodo', 'Early', 'Offline', 'Bank', 'Propelld', 'Corp Inst'];

    // Group by batch
    const grouped: any = {};

    payments.forEach(p => {
      let b = p.batch?.batch?.trim() || 'Others';
      // normalize 'Reco ' to 'Reco'
      if (b === 'Reco ') b = 'Reco';

      if (!grouped[b]) {
        grouped[b] = {};
        sources.forEach(s => grouped[b][s] = 0);
        grouped[b].Total = 0;
      }

      const amt = p.amount || 0;
      grouped[b][p.sourceName] = (grouped[b][p.sourceName] || 0) + amt;
      grouped[b].Total += amt;
    });

    // Convert to array
    const data = Object.keys(grouped).map(batch => ({
      batch,
      ...grouped[batch]
    })).sort((a, b) => b.Total - a.Total); // Sort by total descending

    return NextResponse.json({ data, sources });
  } catch (error) {
    console.error('API Error (batch-collections):', error);
    return NextResponse.json({ error: 'Failed to fetch data' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { getSession } from '@/lib/auth';
import * as XLSX from 'xlsx';
import { Prisma } from '@/generated/prisma';
import { buildModelSearchWhere } from '@/lib/prisma-search';
import { formatModelRows, getModelDisplayConfig } from '@/lib/database-display';
import {
  fetchAllPaymentTableRowsForExport,
  isLegacyPaymentModel,
  usesPaymentRawQueries,
} from '@/lib/legacy-payment-tables';
import { fetchConsolidatedPaymentsForExport } from '@/lib/consolidated-payment-export';

export const maxDuration = 300;

export async function GET(request: Request, { params }: { params: Promise<{ model: string }> }) {
  const session = await getSession();

  if (session?.user?.role !== 'ADMIN') {
    return new NextResponse('Unauthorized', { status: 401 });
  }

  const resolvedParams = await params;
  const modelName = resolvedParams.model;

  // Validate that the model exists in Prisma
  if (!(modelName in prisma)) {
    return new NextResponse('Model not found', { status: 404 });
  }

  const modelDmmf = Prisma.dmmf.datamodel.models.find(m => m.name.toLowerCase() === modelName.toLowerCase());
  const hasField = (fieldName: string): boolean =>
    !!modelDmmf?.fields.some(f => f.name === fieldName);

  const url = new URL(request.url);
  const q = url.searchParams.get('q');
  const start = url.searchParams.get('start');
  const end = url.searchParams.get('end');

  try {
    const whereClause: Record<string, unknown> = {};
    const AND: Record<string, unknown>[] = [];

    if (q) {
      const searchConditions = buildModelSearchWhere(modelName, q, hasField);
      if (searchConditions.length > 0) {
        AND.push({ OR: searchConditions });
      }
    }

    if (start || end) {
      const dateFilter: Record<string, Date> = {};
      if (start) dateFilter.gte = new Date(start);
      if (end) {
        const endDate = new Date(end);
        endDate.setHours(23, 59, 59, 999);
        dateFilter.lte = endDate;
      }

      if (hasField('date')) {
        AND.push({ date: dateFilter });
      } else if (hasField('createdAt')) {
        AND.push({ createdAt: dateFilter });
      }
    }

    if (AND.length > 0) {
      whereClause.AND = AND;
    }

    const displayConfig = getModelDisplayConfig(modelName);
    const paymentRaw = isLegacyPaymentModel(modelName) && (await usesPaymentRawQueries(modelName));
    const isConsolidatedPayment =
      modelName === 'consolidatedPayment' || modelName === 'ConsolidatedPayment';

    let data: Record<string, unknown>[];

    if (isConsolidatedPayment) {
      // Raw SQL avoids Prisma P2020 on invalid MySQL zero-dates in `date`
      data = await fetchConsolidatedPaymentsForExport({
        q: q || undefined,
        start: start || undefined,
        end: end || undefined,
      });
    } else if (paymentRaw) {
      data = await fetchAllPaymentTableRowsForExport(modelName, {
        q: q || undefined,
        start: start || undefined,
        end: end || undefined,
      });
    } else {
      const findManyArgs: Record<string, unknown> = {
        where: whereClause,
        orderBy: { id: 'desc' },
      };
      if (displayConfig?.include) {
        findManyArgs.include = displayConfig.include;
      }

            const rawData = await (prisma as any)[modelName].findMany(findManyArgs);
      data = formatModelRows(modelName, rawData);
    }

    if (data.length === 0) {
      return new NextResponse('No data found to export', { status: 404 });
    }

    // Format data for Excel
    const formattedData = data.map((row: Record<string, unknown>) => {
      const formatted: Record<string, unknown> = {};
      for (const [key, val] of Object.entries(row)) {
        if (val instanceof Date) {
          formatted[key] = val.toISOString().replace('T', ' ').slice(0, 19);
        } else if (typeof val === 'object' && val !== null) {
          formatted[key] = JSON.stringify(val);
        } else {
          formatted[key] = val;
        }
      }
      return formatted;
    });

    // Create workbook
    const wb = XLSX.utils.book_new();
    const ws = XLSX.utils.json_to_sheet(formattedData);

    // Auto-size columns
    const headers = Object.keys(formattedData[0]);
    ws['!cols'] = headers.map(h => ({
      wch: Math.max(h.length, 15)
    }));

    XLSX.utils.book_append_sheet(wb, ws, modelName);

    // Generate buffer
    const buf = XLSX.write(wb, { type: 'buffer', bookType: 'xlsx' });

    const fileName = `${modelName}_export_${new Date().toISOString().split('T')[0]}.xlsx`;

    return new NextResponse(buf, {
      headers: {
        'Content-Type': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        'Content-Disposition': `attachment; filename="${fileName}"`,
      },
    });

  } catch (error) {
    console.error('Export error:', error);
    return new NextResponse('Failed to export data', { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { getSession } from '@/lib/auth';
import { parseDateInput } from '@/lib/dates';
import {
  resolveAdmissionFormLookups,
  resolveBatchFk,
  resolvePaymentOptionFk,
  resolveProgramFk,
} from '@/lib/lookups';
import {
  processPaymentUpload,
} from '@/lib/payment-upload';
import { getPaymentSource, type PaymentUploadSlug } from '@/lib/payment-sources';
import { saveLegacyAdmissionForm } from '@/lib/legacy-admission-form';
import { processConsolidatedPayoutUpload } from '@/lib/consolidated-payout-upload';

export async function POST(req: NextRequest, context: { params: Promise<{ type: string }> }) {
  try {
    const session = await getSession();
    if (session?.user?.role !== 'ADMIN') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { type } = await context.params;
    const body = await req.json();
    const { data, category } = body;

    if (!data || !Array.isArray(data)) {
      return NextResponse.json({ error: 'Invalid data format' }, { status: 400 });
    }

    const processInChunks = async <T,>(items: T[], fn: (item: T) => Promise<unknown>, chunkSize = 5) => {
      let count = 0;
      for (let i = 0; i < items.length; i += chunkSize) {
        const chunk = items.slice(i, i + chunkSize);
        const results = [];
        for (const item of chunk) {
          try {
            results.push(await fn(item));
          } catch (err) {
            console.error('Error processing item:', err);
            throw err;
          }
        }
        count += results.filter(r => r !== null && r !== undefined).length;
      }
      return count;
    };

    if (type === 'fee') {
      const count = await processInChunks(data, async (row: any) => {
        if (!row.batch || !row.payment_option || !row.program) return null;

        const [batchId, paymentOptionId, programId] = await Promise.all([
          resolveBatchFk(row.batch),
          resolvePaymentOptionFk(row.payment_option),
          resolveProgramFk(row.program),
        ]);
        if (!batchId || !paymentOptionId || !programId) return null;

        await prisma.feeStructure.upsert({
          where: {
            batchId_paymentOptionId_programId: {
              batchId,
              paymentOptionId,
              programId,
            },
          },
          update: {
            semFee: parseFloat(row.sem_fee) || 0,
          },
          create: {
            batchId,
            paymentOptionId,
            programId,
            semFee: parseFloat(row.sem_fee) || 0,
          },
        });
        return true;
      });
      return NextResponse.json({ success: true, count });
    }

    if (getPaymentSource(type)) {
      const count = await processPaymentUpload(type as PaymentUploadSlug, data);
      return NextResponse.json({ success: true, count });
    }

    if (type === 'consolidated-payout') {
      const count = await processConsolidatedPayoutUpload(data, category);
      return NextResponse.json({ success: true, count });
    }

    if (type === 'form') {
      const count = await processInChunks(data, async (row: any) => {
        const enrollmentRef =
          row.Enrollment_No ??
          row['Enrollment No'] ??
          row.enrollment_id ??
          row.enrollmentId ??
          row.enrollmentNo ??
          row.EnrollmentNo ??
          row.enrollment_no;
        if (enrollmentRef === undefined || enrollmentRef === null || enrollmentRef === '') return null;

        const doa = parseDateInput(
          row.Date_of_Admission ||
            row.doa ||
            row.DOA ||
            row.DateOfAdmission ||
            row['Date of Admission'] ||
            row['Date Of Admission']
        );

        const lookups = await resolveAdmissionFormLookups({
          enrollmentNo: enrollmentRef,
          program: row.Program ?? row.program ?? null,
          paymentOption:
            row.Payment_option ??
            row.PaymentOption ??
            row['Payment Option'] ??
            row.paymentOption ??
            row.payment_option ??
            null,
          batch: row.Batch ?? row.batch ?? null,
          type: row.Type ?? row.type ?? null,
          status: row.Status ?? row.status ?? null,
          team: row.Team ?? row.team ?? null,
          bifurcation: row.Bifurcation ?? row.bifurcation ?? null,
          nationality: row.nationality ?? row.Nationality ?? null,
          location: row.Location ?? row.location ?? null,
          placedStatus: row['Placed Status'] ?? row.PlacedStatus ?? row.placed_status ?? null,
          leadSource: row.Lead_source ?? row['Lead Source'] ?? row.leadSource ?? null,
          ugcStatus: row.UGC_Status ?? row['UGC Status'] ?? row.ugcStatus ?? null,
          counselor: row.Councellor ?? row.Counselor ?? row.counselor ?? null,
        });

        if (!lookups.enrollmentId) return null;

        const enrollmentText =
          typeof enrollmentRef === 'string' && !/^\d+$/.test(enrollmentRef.trim())
            ? enrollmentRef.trim()
            : undefined;

        await saveLegacyAdmissionForm(null, {
          enrollmentNo: enrollmentText ?? enrollmentRef,
          program: row.Program ?? row.program ?? null,
          paymentOption:
            row.Payment_option ??
            row.PaymentOption ??
            row['Payment Option'] ??
            row.paymentOption ??
            row.payment_option ??
            null,
          batch: row.Batch ?? row.batch ?? null,
          type: row.Type ?? row.type ?? null,
          status: row.Status ?? row.status ?? null,
          team: row.Team ?? row.team ?? null,
          bifurcation: row.Bifurcation ?? row.bifurcation ?? null,
          nationality: row.nationality ?? row.Nationality ?? null,
          location: row.Location ?? row.location ?? null,
          placedStatus: row['Placed Status'] ?? row.PlacedStatus ?? row.placed_status ?? null,
          leadSource: row.Lead_source ?? row['Lead Source'] ?? row.leadSource ?? null,
          ugcStatus: row.UGC_Status ?? row['UGC Status'] ?? row.ugcStatus ?? null,
          counselor: row.Councellor ?? row.Counselor ?? row.counselor ?? null,
          sno: parseInt(row.Sno || row.sno, 10) || null,
          doa,
          name: row.Name || row.name || null,
          aadhaar: row.Adhar || row.Aadhaar || row.aadhaar || null,
        });
        return true;
      });
      return NextResponse.json({ success: true, count });
    }

    return NextResponse.json({ error: 'Invalid upload type' }, { status: 400 });
  } catch (error: unknown) {
    console.error('Upload Error:', error);
    return NextResponse.json({ error: (error instanceof Error ? error.message : String(error)) }, { status: 500 });
  }
}
